import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`real-estate-developments`,heroTitle:`Track real estate developments in minutes`,heroSubtitle:`Perplexity Computer monitors permits, maps active projects, and builds your deal tracker — automatically.`,heroCta:`Track my market`,inputUrlCta:`Track my market`,inputUrlPlaceholder:`e.g. Austin TX multifamily`,inputUrlPrefill:`Go to {url} and research all active and upcoming real estate developments for this market. 1) Monitor recent permit filings, zoning board decisions, and local real estate news. 2) Identify active development projects including project name, developer, project type, estimated timeline, and current deal stage. 3) Find contact information for each developer including company website, phone, and email where available. 4) Map all developments by neighborhood or submarket. 5) Deliver a project tracker spreadsheet with columns for project name, developer, project type, address, deal stage, estimated completion, and contact information.`,heroOverlaySteps:[`Scanning permit filings and zoning board records for your market`,`Identifying active developments with developer names, timelines, and deal stages`,`Pulling contact information and mapping projects by submarket`,`Project tracker with deal stages, timelines, and contacts — ready to prospect`],generatingSteps:[`Researching {url} to identify the target market, project types, and geographic scope`,`Designing an agent to monitor permit filings, zoning boards, and real estate news sources`,`Configuring developer identification, contact enrichment, and deal stage classification`,`Setting up the project tracker spreadsheet with mapping and ongoing monitoring`],featureSectionTitle:`From city name to deal pipeline`,featureCardTitles:[`Connects to your real estate stack`,`Outputs you can prospect`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Salesforce, HubSpot, Google Maps, Notion — Computer plugs into your tools so permit tracking, contact enrichment, and deal management happen in one workflow.`,`Project tracker spreadsheets. Developer contact lists. Submarket maps. Zoning change alerts. Computer delivers actionable intel formatted for your pipeline.`],capabilitySectionTitle:`Your deal sourcing, on autopilot`,capabilitySectionSubtitle:`Enter a market, step away, come back to a complete development tracker.`,capabilityCards:[{title:`Permit Monitoring`,description:`Computer can scan municipal permit filings and zoning board agendas — surfacing new projects before they hit the market.`},{title:`Developer Research`,description:`Computer can identify developers behind each project, pull company details, and find direct contact information for outreach.`},{title:`Market Mapping`,description:`Computer can map active developments by submarket, project type, and timeline — giving you a visual read on where activity is concentrated.`},{title:`Connect Your Tools`,description:`Computer can read and write to Google Sheets, Salesforce, HubSpot, Notion, and more — build workflows across your entire deal sourcing stack.`},{title:`Remember & Learn`,description:`Computer can remember your target markets, project preferences, and developer relationships across sessions — so every scan builds on what came before.`},{title:`Monitor & Alert`,description:`Computer can watch for new permit filings and zoning changes daily — set up a monitoring workflow that pings you when a new development hits your market.`}]});export{t as default};
